// Owner request: the GGS home page shows the real prices from the men's and women's price lists
// (services generated by pricelist-services.ts), names which studio takes each booking, and shows
// both studios' separate WhatsApp and Instagram. Runs after patch-whatsapp.mjs.
// Usage: node patch-beranda.mjs <ggs-visit app dir>
import fs from "node:fs";
import path from "node:path";
const app = process.argv[2];
const file = path.join(app, "src/App.tsx");
let s = fs.readFileSync(file, "utf8");
const swap = (from, to, all = false) => {
  const hit = typeof from === "string" ? s.includes(from) : from.test(s);
  if (!hit) throw new Error(`patch-beranda: "${String(from).slice(0, 70)}" not found`);
  if (typeof from !== "string") from.lastIndex = 0;
  s = all && typeof from === "string" ? s.split(from).join(to) : s.replace(from, to);
};
const aud = "(service as any).audience";

// Home carousels: the highlighted rows of each price list.
swap("(service) => service.active && audienceCategoryMap.men.has(service.category.trim().toLowerCase()),",
  `(service) => service.active && ${aud} === 'pria' && (service as any).featured,`);
swap("(service) => service.active && homeWomenServiceNames.has(service.name.trim().toLowerCase()),",
  `(service) => service.active && ${aud} === 'wanita' && (service as any).featured,`);

// Headings name the studio and link to the full price list.
swap("<p className=\"clearer-kicker\">MEN'S GROOMING</p>", "<p className=\"clearer-kicker\">GGS BARBER STUDIO</p>");
swap("Layanan pria\n              <br />\n              <em>aktif di GGS.</em>", "Pricelist\n              <br />\n              <em>barber pria.</em>");
swap("<p className=\"home-mens-grooming-intro\">Pilihan layanan pria yang tersedia saat ini, dengan detail durasi dan harga dari GGS.</p>",
  "<p className=\"home-mens-grooming-intro\">Harga dari Pricelist Pria. Booking langsung ke WhatsApp GGS Barber Studio 0813-3335-9200. <Link href=\"/pricelist-pria\" className=\"home-pricelist-link\" data-testid=\"link-home-pricelist-pria\">Lihat pricelist pria lengkap <ArrowRight size={14} aria-hidden=\"true\" /></Link></p>");
swap("<p className=\"clearer-kicker\">WOMEN'S HAIR &amp; BEAUTY</p>", "<p className=\"clearer-kicker\">GGS BEAUTY</p>");
swap("Layanan wanita\n              <br />\n              <em>di GGS.</em>", "Pricelist\n              <br />\n              <em>GGS Beauty.</em>");
swap("<p className=\"home-mens-grooming-intro\">Pilihan potong, warna, perawatan, dan styling rambut wanita, lengkap dengan durasi dan harga.</p>",
  "<p className=\"home-mens-grooming-intro\">Harga dari Pricelist Wanita. Booking langsung ke WhatsApp GGS Beauty 0823-4277-7723. <Link href=\"/pricelist-wanita\" className=\"home-pricelist-link\" data-testid=\"link-home-pricelist-wanita\">Lihat pricelist wanita lengkap <ArrowRight size={14} aria-hidden=\"true\" /></Link></p>");

// Prices show the list's own wording (ranges, "Mulai"); rows without a duration show the studio instead.
swap("{money(service.price)}", `{(service as any).priceLabel ?? money(service.price)}`, true);
let durations = 0;
s = s.replace(/<span className="home-mens-service-duration">(\s*)<Clock3 size=\{14\} aria-hidden="true" \/>(\s*)\{service\.durationMinutes\} menit(\s*)<\/span>/g,
  (_m, a, b, c) => (durations++, `<span className="home-mens-service-duration">{service.durationMinutes > 0 ? (<>${a}<Clock3 size={14} aria-hidden="true" />${b}{service.durationMinutes} menit${c}</>) : (${aud} === 'pria' ? 'GGS Barber' : 'GGS Beauty')}</span>`));
if (durations !== 2) throw new Error(`patch-beranda: expected 2 home durations, patched ${durations}`);
swap("<span className=\"clearer-duration\"><Clock3 size={15} /> {service.durationMinutes} menit</span>",
  `<span className="clearer-duration">{service.durationMinutes > 0 ? <><Clock3 size={15} /> {service.durationMinutes} menit</> : (${aud} === 'pria' ? 'GGS Barber' : 'GGS Beauty')}</span>`);
swap("Booking layanan\n", "Booking via WhatsApp\n", true);

// Services pages for men and women list that price list.
swap("const audienceServices = services.filter((service) => categories.has(service.category.trim().toLowerCase()));",
  `const audienceServices = services.filter((service) => audience === 'men' ? ${aud} === 'pria' : audience === 'women' ? ${aud} === 'wanita' : categories.has(service.category.trim().toLowerCase()));`);

// Booking form: services grouped by studio, so the request goes to the right WhatsApp.
swap(/\{services\.map\(\(service\) => <option value=\{service\.id\} key=\{service\.id\}>\{service\.name\} · \{[^}]*\} · \{service\.durationMinutes\} menit<\/option>\)\}/,
  `{([['pria', 'Pria · GGS Barber Studio'], ['wanita', 'Wanita · GGS Beauty']] as const).map(([group, label]) => (
                    <optgroup label={label} key={group}>
                      {services.filter((service) => ${aud} === group).map((service) => <option value={service.id} key={service.id}>{service.name} · {(service as any).priceLabel ?? money(service.price)}{service.durationMinutes > 0 ? \` · \${service.durationMinutes} menit\` : ''}</option>)}
                    </optgroup>
                  ))}`);

// Footer: both studios with their own WhatsApp and Instagram.
swap("<p>© {new Date().getFullYear()} {site?.brandName?.trim() || 'GGS Hair Studio'}. Studio rambut, dimulai dari percakapan.</p>",
  `<div className="ggs-footer-studios" data-testid="footer-studios">
          <div><strong>GGS Barber Studio</strong><span>Khusus pria</span><a href="https://wa.me/6281333359200" target="_blank" rel="noreferrer" data-testid="link-footer-wa-pria">WA 0813-3335-9200</a><a href="https://instagram.com/hairstudio.ggs.grt" target="_blank" rel="noreferrer">@hairstudio.ggs.grt</a></div>
          <div><strong>GGS Beauty</strong><span>Wanita &amp; perawatan</span><a href="https://wa.me/6282342777723" target="_blank" rel="noreferrer" data-testid="link-footer-wa-wanita">WA 0823-4277-7723</a><a href="https://instagram.com/ggsbeauty.hair.co" target="_blank" rel="noreferrer">@ggsbeauty.hair.co</a></div>
          <p>© {new Date().getFullYear()} {site?.brandName?.trim() || 'GGS Hair Studio'}. Studio rambut, dimulai dari percakapan.</p>
        </div>`);
fs.writeFileSync(file, s);

const css = path.join(app, "src/homepage.css");
const marker = "/* GGS home page price lists (patch-beranda.mjs) */";
const c = fs.readFileSync(css, "utf8");
if (!c.includes(marker)) fs.writeFileSync(css, c + `
${marker}
.home-pricelist-link { display: inline-flex; align-items: center; gap: 6px; margin-top: 8px; color: var(--clearer-accent); font-weight: 700; font-size: 13px; text-decoration: underline; text-underline-offset: 3px; }
.home-mens-service-duration { font-size: 12px; }
.ggs-footer-studios { display: grid; grid-template-columns: repeat(2, minmax(0, max-content)); gap: 14px 36px; }
.ggs-footer-studios > div { display: flex; flex-direction: column; gap: 3px; font-size: 13px; }
.ggs-footer-studios > div > span { color: var(--clearer-muted); font-size: 12px; }
.ggs-footer-studios a { color: inherit; text-decoration: underline; text-underline-offset: 3px; }
.ggs-footer-studios > p { grid-column: 1 / -1; margin: 4px 0 0; color: var(--clearer-muted); font-size: 13px; }
@media (max-width: 520px) { .ggs-footer-studios { grid-template-columns: 1fr 1fr; gap: 12px 18px; } }
`);
console.log("GGS home page uses the real price lists");
